std::string pipeName(){HANDLE token=nullptr;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token))throw std::runtime_error("Cannot read Windows identity.");Handle t(token);DWORD n=0;GetTokenInformation(t.h,TokenUser,nullptr,0,&n);Bytes data(n);if(!GetTokenInformation(t.h,TokenUser,data.data(),n,&n))throw std::runtime_error("Cannot read Windows identity.");LPWSTR value=nullptr;if(!ConvertSidToStringSidW(((TOKEN_USER*)data.data())->User.Sid,&value))throw std::runtime_error("Cannot read Windows SID.");auto sid=utf8(value);LocalFree(value);std::replace(sid.begin(),sid.end(),'-','_');std::string name="udm-"+sid;wchar_t suffix[40];DWORD size=GetEnvironmentVariableW(L"UDM_INSTANCE_TAG",suffix,40);if(size>0&&size<40){auto tag=utf8(std::wstring(suffix,size));if(!std::regex_match(tag,std::regex("[A-Za-z0-9_-]{1,32}")))throw std::runtime_error("Invalid instance tag.");name+="-"+tag;}return name;}
static void pipeIo(HANDLE pipe,void* buffer,DWORD count,bool write,DWORD timeout,HANDLE stop=nullptr){auto bytes=(BYTE*)buffer;while(count){OVERLAPPED ov{};Handle event(CreateEventW(nullptr,TRUE,FALSE,nullptr));ov.hEvent=event.h;DWORD n=0;BOOL ok=write?WriteFile(pipe,bytes,count,&n,&ov):ReadFile(pipe,bytes,count,&n,&ov);if(!ok){if(GetLastError()!=ERROR_IO_PENDING)throw std::runtime_error("Browser connection closed.");HANDLE waits[]={event.h,stop};DWORD state=WaitForMultipleObjects(stop?2:1,waits,FALSE,timeout);if(state!=WAIT_OBJECT_0){CancelIoEx(pipe,&ov);GetOverlappedResult(pipe,&ov,&n,TRUE);throw std::runtime_error("Browser connection timed out.");}if(!GetOverlappedResult(pipe,&ov,&n,FALSE))throw std::runtime_error("Browser connection closed.");}if(!n)throw std::runtime_error("Browser connection closed.");count-=n;bytes+=n;}}
static Json readMessage(HANDLE pipe,DWORD timeout,HANDLE stop=nullptr){DWORD n=0;pipeIo(pipe,&n,4,false,timeout,stop);if(n<1||n>256*1024)throw std::runtime_error("Message exceeds the 256 KB limit.");std::string s(n,0);pipeIo(pipe,s.data(),n,false,timeout,stop);return Json::parse(s);}
static void writeMessage(HANDLE pipe,const Json& j,DWORD timeout,HANDLE stop=nullptr){auto s=j.dump();DWORD n=(DWORD)s.size();if(n>256*1024)throw std::runtime_error("Reply exceeds the 256 KB limit.");pipeIo(pipe,&n,4,true,timeout,stop);pipeIo(pipe,s.data(),n,true,timeout,stop);}
Json send(const Json& j,int timeout){auto name=L"\\\\.\\pipe\\"+wide(pipeName());auto deadline=GetTickCount64()+timeout;for(;;){Handle pipe(CreateFileW(name.c_str(),GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_EXISTING,FILE_FLAG_OVERLAPPED,nullptr));if(pipe){writeMessage(pipe.h,j,10000);return readMessage(pipe.h,10000);}DWORD error=GetLastError();if(error!=ERROR_FILE_NOT_FOUND&&error!=ERROR_PIPE_BUSY)throw std::runtime_error("Cannot open UDM browser connection (Windows error "+std::to_string(error)+").");if(GetTickCount64()>=deadline)throw std::runtime_error("UDM browser connection is not ready.");WaitNamedPipeW(name.c_str(),100);Sleep(30);}}
JobPtr Manager::receive(const Json& message){
 if(str(message,"action")=="cli-add"){
  Lock lock(mutex);auto previous=jobs;
  auto job=offerDownload(str(message,"url"),str(message,"folder"),str(message,"filename"),"Main queue",true);
  bool existing=std::find(previous.begin(),previous.end(),job)!=previous.end();
  if(str(job->data,"DuplicateOf").empty()){
   if(existing)pendingOffers.push_back(job); // Never reset an active or completed record.
   else job->data["Status"]=yes(message,"paused")?"Paused":yes(message,"silent")?"Queued":"Awaiting confirmation";
  }
  save();return job;
 }
if(str(message,"action")=="adaptive")return receiveAdaptive(*this,message);auto action=str(message,"action"),address=str(message,"url");if(action!="add"&&action!="media"&&action!="sabr")throw std::runtime_error("Unknown UDM command.");Headers h;for(auto pair:{std::pair<const char*,const char*>{"referrer","Referer"},{"cookies","Cookie"},{"userAgent","User-Agent"}}){auto v=str(message,pair.first);if(!v.empty())h[pair.second]=v;}validateHeaders(h);if(action=="add"){auto replacement=captureAddressRefresh(address,h,str(message,"filename"),str(message,"referrer"));if(replacement)return replacement;Lock lock(mutex);auto previous=jobs;auto job=offerDownload(address,"",str(message,"filename"),"Main queue",true,h);bool existing=std::find(previous.begin(),previous.end(),job)!=previous.end();if(!existing&&!str(message,"referrer").empty()){Url page(str(message,"referrer"));if(page.scheme=="http"||page.scheme=="https")job->data["DownloadPage"]=page.full;}if(str(job->data,"DuplicateOf").empty()){if(existing&&(str(job->data,"Status")=="Complete"||isActive(job)||str(job->data,"Status")=="Queued"))pendingOffers.push_back(job);else job->data["Status"]=yes(state["Settings"],"SkipBrowserFileInfo")?"Queued":"Awaiting confirmation";}save();return job;}auto height=num(message,"height"),pixel=num(message,"pixelHeight");auto format=str(message,"formatId");if(action!="add"){validateSource(address);if(height<144||height>4320||pixel<0||pixel>4320||(!format.empty()&&!std::regex_match(format,std::regex("[0-9]{1,6}"))))throw std::runtime_error("Invalid captured stream dimensions or format.");if(action=="sabr"){if(!message.contains("sabr"))throw std::runtime_error("Browser streaming capture is missing.");validateSabr(message["sabr"],address);if(pixel<1)throw std::runtime_error("Captured stream dimensions are missing.");}else{if(str(message,"videoUrl").empty())throw std::runtime_error("UDM needs a captured playback link. Choose the quality in the browser panel.");validateStream(str(message,"videoUrl"));if(!str(message,"audioUrl").empty())validateStream(str(message,"audioUrl"));}if(!fs::exists(appDir()/L"tools"/L"ffmpeg.exe"))throw std::runtime_error("Media helper missing. Run setup-media.ps1.");}Lock l(mutex);for(auto j:jobs){auto status=str(j->data,"Status");if(str(j->data,"Url")==address&&(status=="Queued"||status=="Awaiting confirmation"||isActive(j))&&((action=="add"&&str(j->data,"SourceUrl").empty())||(action!="add"&&!str(j->data,"SourceUrl").empty()&&num(j->data,"MediaHeight")==height&&yes(j->data,"ExactMediaQuality")==yes(message,"exactQuality")&&str(j->data,"MediaFormatId")==format)))return j;}auto name=str(message,"filename");if(action!="add"){if(name.empty())name="YouTube video";std::replace(name.begin(),name.end(),'/','_');std::replace(name.begin(),name.end(),'\\','_');name=std::regex_replace(name,std::regex("\\.(mp4|mkv|webm)$",std::regex::icase),"")+".mp4";}auto j=add(address,"",name,"Main queue",true,h);try{if(action=="add"&&!str(message,"referrer").empty()){Url page(str(message,"referrer"));if(page.scheme=="http"||page.scheme=="https")j->data["DownloadPage"]=page.full;}if(action!="add"){j->data["SourceUrl"]=address;j->data["MediaHeight"]=height;j->data["MediaPixelHeight"]=pixel;j->data["ExactMediaQuality"]=action=="sabr"||yes(message,"exactQuality");j->data["MediaFormatId"]=format;if(action=="sabr"){j->data["ProtectedSabr"]=protect(message["sabr"].dump());j->data["MediaFormatId"]=str(message["sabr"]["video"],"id");setStreams(*this,j,str(message["sabr"],"url"),str(message["sabr"],"url"));}else setStreams(*this,j,str(message,"videoUrl"),str(message,"audioUrl"));j->data["FormatDescription"]="Browser capture - "+std::to_string(height)+"p";}j->data["Status"]=yes(state["Settings"],"SkipBrowserFileInfo")?"Queued":"Awaiting confirmation";save();return j;}catch(...){jobs.erase(std::remove(jobs.begin(),jobs.end(),j),jobs.end());save();throw;}}
PipeServer::PipeServer(Manager& m,std::function<void()> s):manager(m),show(std::move(s)){stopEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);if(!stopEvent)throw std::runtime_error("Cannot initialize browser integration.");thread=std::thread([this]{listen();});}
PipeServer::~PipeServer(){stopping=true;SetEvent(stopEvent);if(thread.joinable())thread.join();CloseHandle(stopEvent);}
void PipeServer::listen(){try{HANDLE token=nullptr;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token))throw std::runtime_error("Cannot read Windows identity.");Handle t(token);DWORD n=0;GetTokenInformation(t.h,TokenUser,nullptr,0,&n);Bytes data(n);if(!GetTokenInformation(t.h,TokenUser,data.data(),n,&n))throw std::runtime_error("Cannot read Windows identity.");LPWSTR sid=nullptr;ConvertSidToStringSidW(((TOKEN_USER*)data.data())->User.Sid,&sid);if(!sid)throw std::runtime_error("Cannot read Windows identity.");std::wstring acl=L"D:P(A;;GA;;;"+std::wstring(sid)+L")";LocalFree(sid);PSECURITY_DESCRIPTOR descriptor=nullptr;if(!ConvertStringSecurityDescriptorToSecurityDescriptorW(acl.c_str(),SDDL_REVISION_1,&descriptor,nullptr))throw std::runtime_error("Cannot secure browser connection.");std::unique_ptr<void,decltype(&LocalFree)> security(descriptor,LocalFree);SECURITY_ATTRIBUTES sa{sizeof(sa),descriptor,FALSE};auto name=L"\\\\.\\pipe\\"+wide(pipeName());while(!stopping){Handle pipe(CreateNamedPipeW(name.c_str(),PIPE_ACCESS_DUPLEX|FILE_FLAG_OVERLAPPED|FILE_FLAG_FIRST_PIPE_INSTANCE,PIPE_TYPE_BYTE|PIPE_READMODE_BYTE|PIPE_WAIT|PIPE_REJECT_REMOTE_CLIENTS,1,4096,4096,0,&sa));if(!pipe)throw std::runtime_error("Cannot create UDM browser connection. Another UDM instance may be running.");Handle ready(CreateEventW(nullptr,TRUE,FALSE,nullptr));OVERLAPPED ov{};ov.hEvent=ready.h;BOOL connected=ConnectNamedPipe(pipe.h,&ov);DWORD error=connected?ERROR_SUCCESS:GetLastError();if(!connected&&error==ERROR_IO_PENDING){HANDLE waits[]={ready.h,stopEvent};if(WaitForMultipleObjects(2,waits,FALSE,INFINITE)!=WAIT_OBJECT_0){CancelIoEx(pipe.h,&ov);DWORD ignored;GetOverlappedResult(pipe.h,&ov,&ignored,TRUE);break;}DWORD ignored;if(!GetOverlappedResult(pipe.h,&ov,&ignored,FALSE))continue;}else if(!connected&&error!=ERROR_PIPE_CONNECTED)continue;try{Json reply;try{auto message=readMessage(pipe.h,10000,stopEvent);auto action=str(message,"action");if(action=="ping")reply={{"ok",true}};else if(action=="diagnostics"){Lock l(manager.mutex);reply={{"ok",true},{"version","0.16.1"},{"dataDirectory",utf8(manager.root.wstring())},{"downloads",manager.jobs.size()}};}else if(action=="preferences"){Lock l(manager.mutex);reply={{"ok",true},{"extensions",words(str(manager.state["Settings"],"CaptureExtensions"))},{"excluded",words(str(manager.state["Settings"],"CaptureExcludedHosts"))}};}else if(action=="show"){show();reply={{"ok",true}};}else{auto j=manager.receive(message);reply={{"ok",true},{"id",j->id()}};if(action!="cli-add"||!yes(message,"background"))show();}}catch(const std::exception& e){reply={{"ok",false},{"error",e.what()}};}writeMessage(pipe.h,reply,10000,stopEvent);/* DisconnectNamedPipe discards unread reply bytes. Wait for client close with a cancellable deadline. */BYTE end=0;try{pipeIo(pipe.h,&end,1,false,10000,stopEvent);}catch(...) {}}catch(...){}DisconnectNamedPipe(pipe.h);}}catch(const std::exception& e){Lock l(manager.mutex);manager.storageError=e.what();}}
int nativeHost(){try{auto input=GetStdHandle(STD_INPUT_HANDLE),output=GetStdHandle(STD_OUTPUT_HANDLE);auto exact=[](HANDLE h,void* b,DWORD n,bool write){BYTE* at=(BYTE*)b;while(n){DWORD done=0;BOOL ok=write?WriteFile(h,at,n,&done,nullptr):ReadFile(h,at,n,&done,nullptr);if(!ok||!done)throw std::runtime_error("Native message stream closed.");n-=done;at+=done;}};DWORD n=0;exact(input,&n,4,false);if(n<1||n>262144)return 1;std::string text(n,0);exact(input,text.data(),n,false);Json reply;try{auto request=Json::parse(text);if(str(request,"action")=="cli-add")throw std::runtime_error("Command-line requests must come from the local UDM executable.");try{reply=send(request,1000);}catch(const std::exception&){auto exe=appDir()/L"UDM.exe";auto command=quote(exe.wstring())+L" --background";STARTUPINFOW si{sizeof(si)};PROCESS_INFORMATION pi{};if(!CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,appDir().c_str(),&si,&pi))throw std::runtime_error("Could not start UDM.");CloseHandle(pi.hThread);CloseHandle(pi.hProcess);reply=send(request,12000);}}catch(const std::exception& e){reply={{"ok",false},{"error",e.what()}};}text=reply.dump();n=(DWORD)text.size();exact(output,&n,4,true);exact(output,text.data(),n,true);return 0;}catch(...){return 1;}}
